      "reason_rule": "One sentence with a next step to inspect the evidence.",
      "resale_permitted": "resale permitted",
      "song_key": "Song link key.",
      "source_keys": "source keys",
      "title_text": "Song title from the daily identity.",
      "value": "Positive component value; no percentile or second score.",
      "window_days": "Elapsed UTC days back to the observed Shazam baseline, or the configured playlist or stream window."
