      "platform_track_id": "Track identifier on the platform, null for an item representing a release rather than a track.",
      "playlist_id": "Playlist identifier on its platform, which must be joined with platform and variant.",
      "position": "One-based item position at the event sighting, or the last sighting before a removal.",
      "previous_position": "One-based position in the previous complete observation at a unique time within this membership island, null when no comparison exists.",
      "recording_method": "Method that resolves the recording as of the bound daily close identified by daily_manifest_close_no and as_of, null when no match is accepted at that close.",
      "removed_after": "UTC time of the last complete sighting before a proven removal, null when the island has no complete presence proof or no later absence.",
      "removed_by": "UTC time of the first complete observation proving absence after this membership island, null when no such observation exists.",
      "resale_permitted": "True only when the contributing source permissions allow resale of this row, with unknown permission treated as false.",
      "snapshot_id": "Identifier of the observation proving the event, including the absence snapshot for a removal.",
      "source_keys": "JSON array of contributing source identifiers used to attach permissions without removing the row.",
      "stream": "Observation stream, where head covers the visible beginning and full covers the full-list collection surface.",
      "uncertainty_hours": "Hours between the two observations bounding this entry, removal or move, null for an entry with no known earlier absence.",
      "variant": "Market or other version of the playlist, kept separate because its contents can differ."
